func DispatchTTSHarness(d, p, m byte, state *TTSHarnessState) error {
	identity, err := ResolveTTSHarnessIdentity(d, p, m)
	if err != nil {
		return err
	}
	handler := TTSHarnessTable[identity.Code]
	if handler == nil {
		return errors.New("tts harness kernel not initialized")
	}
	return handler(identity, state)
}

func GetTTSHarnessExecutionCount(code uint16) uint64 {
	if code >= 1000 { return 0 }
	return atomic.LoadUint64(&TTSHarnessMetrics[code])
}